      coap_show_pdu(COAP_LOG_ERR, pdu);
      coap_pdu_encode_header(pdu, COAP_PROTO_UDP);
      coap_delete_string(query);
      coap_delete_string(uri_path);
    }
    coap_delete_pdu(pdu);
  }
  coap_cleanup();
  return 0;
}
